using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF Core 9 renamed "Discriminator" → "$type".
        // Opt back in so existing documents with "Discriminator" still map correctly,
        // and raw SQL like `WHERE c.Discriminator = 'Blog'` keeps working.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: EF Core 9 changed the id format from "EntityType|KeyValue"
        // to just "KeyValue". Opt back in to the legacy format for existing documents.
        modelBuilder.Entity<Blog>().UsePropertyAccessMode(PropertyAccessMode.Property);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdGenerator>();

        // Breaking change 3: EF Core 9 removed support for defining Cosmos DB indexes
        // via HasIndex(). Manage indexes via the Azure Portal or Cosmos SDK instead.
        // REMOVED: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

